// Live client data for this site. Generated by ConsultPrompts; edits made in
// the dashboard show up here without a redeploy.
(function () {
  'use strict';

  var CLIENT_ID = "1529dc09-ec3e-42f9-9f5b-ee9ce0fa1c20";
  var SUPABASE_URL = "https://ggsoyejwvywgevszwuqt.supabase.co/rest/v1";
  var SUPABASE_ANON_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imdnc295ZWp3dnl3Z2V2c3p3dXF0Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4NDM4MzkyNiwiZXhwIjoyMDk5OTU5OTI2fQ.HiBtOK4q9Hem2f5pAa4jyviTlD43FH38cmTpWcDfGk8";
  if (!CLIENT_ID || !SUPABASE_URL || !SUPABASE_ANON_KEY) return;

  var BRAND_TTL = 5 * 60 * 1000;
  var IMG_TTL = 50 * 60 * 1000; // under Supabase's 1-hour signed-URL expiry
  var WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

  // ── validation: nothing from client data reaches href/src unchecked ──────
  function str(v) { return v == null ? '' : String(v); }
  function list(v) { return Array.isArray(v) ? v : []; }
  function safeHttpURL(v) {
    try {
      var u = new URL(str(v));
      return (u.protocol === 'https:' || u.protocol === 'http:') ? u.href : null;
    } catch (e) { return null; }
  }
  function safeEmail(v) {
    var s = str(v).trim();
    return /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,253}\.[A-Za-z]{2,24}$/.test(s) ? s : null;
  }
  function safePhoneHref(v) {
    var digits = str(v).replace(/[^0-9+]/g, '');
    return /^\+?[0-9]{3,20}$/.test(digits) ? 'tel:' + digits : null;
  }
  // Storage object names are plain file names (e.g. "service-1.png"): no
  // slashes, so a path can never escape this client's folder.
  function safeAssetName(v) {
    var s = str(v);
    return /^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$/.test(s) && s.indexOf('..') === -1 ? s : null;
  }
  function safeFocal(v) {
    var s = str(v).trim();
    return /^[0-9.%a-z\s-]{1,40}$/i.test(s) ? s : null;
  }

  // ── small DOM helpers ────────────────────────────────────────────────────
  function setText(scope, field, value) {
    var el = scope.querySelector('[data-field="' + field + '"]');
    if (el) el.textContent = str(value);
  }
  function cloneTemplate(template) {
    var el = template.cloneNode(true);
    el.removeAttribute('id');
    el.style.display = '';
    return el;
  }
  function clearExcept(container, keep) {
    Array.prototype.slice.call(container.children).forEach(function (c) { if (c !== keep) c.remove(); });
  }
  function showStorageImage(card, name) {
    var file = safeAssetName(name);
    var wrap = card.querySelector('[data-field="image-wrap"]');
    var img = card.querySelector('[data-field="image"]');
    if (!file || !wrap || !img) return;
    wrap.style.display = '';
    signAndSetImageEl(CLIENT_ID + '/' + file, img);
  }

  // ── Supabase access ──────────────────────────────────────────────────────
  function supabaseFetch(path, init) {
    var headers = Object.assign(
      { apikey: SUPABASE_ANON_KEY, Authorization: 'Bearer ' + SUPABASE_ANON_KEY },
      (init && init.headers) || {}
    );
    return fetch(SUPABASE_URL + path, Object.assign({}, init, { headers: headers, credentials: 'omit' }));
  }
  function readCache(key, ttl) {
    try {
      var entry = JSON.parse(localStorage.getItem(key));
      if (!entry || Date.now() - entry.ts > ttl) return null;
      return entry.data;
    } catch (e) { return null; }
  }
  function writeCache(key, data) {
    try { localStorage.setItem(key, JSON.stringify({ ts: Date.now(), data: data })); } catch (e) {}
  }

  // Signs a Storage path and shows it in the given <img>, caching the signed
  // URL. onFail runs when there's no such image (or it fails to load).
  function signAndSetImageEl(path, img, onSuccess, onFail) {
    if (!img) return;
    function show(url) {
      img.onerror = function () { img.style.display = 'none'; if (onFail) onFail(); };
      img.style.display = '';
      img.src = url;
      if (onSuccess) onSuccess();
    }
    var cacheKey = 'cp_img_' + CLIENT_ID;
    var cached = readCache(cacheKey, IMG_TTL) || {};
    if (typeof cached[path] === 'string' && cached[path].indexOf(SUPABASE_URL + '/storage/v1/') === 0) {
      show(cached[path]);
      return;
    }
    supabaseFetch('/storage/v1/object/sign/clients/' + path.split('/').map(encodeURIComponent).join('/'), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ expiresIn: 3600 })
    })
      .then(function (res) { return res.ok ? res.json() : null; })
      .then(function (result) {
        var signed = result && result.signedURL;
        if (typeof signed !== 'string' || signed.charAt(0) !== '/') { if (onFail) onFail(); return; }
        var url = SUPABASE_URL + '/storage/v1' + signed;
        var updated = readCache(cacheKey, IMG_TTL) || {};
        updated[path] = url;
        writeCache(cacheKey, updated);
        show(url);
      })
      .catch(function () { if (onFail) onFail(); });
  }
  function signAndSetImage(path, imgId, onSuccess, onFail) {
    signAndSetImageEl(path, document.getElementById(imgId), onSuccess, onFail);
  }

  // Fixed icon set, matching agency-service's model.SocialPlatforms allowlist.
  // These constants are the only thing this file ever writes as HTML.
  var SOCIAL_ICONS = {
    instagram: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="18" height="18" aria-hidden="true"><rect x="2" y="2" width="20" height="20" rx="5"></rect><circle cx="12" cy="12" r="4"></circle><circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"></circle></svg>',
    facebook: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="18" height="18" aria-hidden="true"><path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z"></path></svg>',
    tiktok: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="18" height="18" aria-hidden="true"><path d="M9 12a4 4 0 1 0 4 4V4c.5 2.5 2.5 4.5 5 5"></path></svg>',
    youtube: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="18" height="18" aria-hidden="true"><rect x="2" y="5" width="20" height="14" rx="4"></rect><path d="M10 9l5 3-5 3z" fill="currentColor" stroke="none"></path></svg>'
  };
  var SOCIAL_LOCATIONS = ['footer', 'hero', 'about'];

  function loadClientData() {
    var brandCacheKey = 'cp_brand_' + CLIENT_ID;
    var cachedBrand = readCache(brandCacheKey, BRAND_TTL);
    Promise.resolve(cachedBrand
      ? cachedBrand
      : supabaseFetch('/rest/v1/clients_public?id=eq.' + encodeURIComponent(CLIENT_ID) + '&select=socials,services,location,hero_focal_desktop,hero_focal_mobile,reviews,menu,about_me')
          .then(function (res) { return res.ok ? res.json() : null; })
          .then(function (rows) {
            var d = Array.isArray(rows) ? rows[0] : null;
            if (d) writeCache(brandCacheKey, d);
            return d;
          })
    ).then(function (data) {
      if (!data || typeof data !== 'object') return;

      var heroImgEl = document.getElementById('hero-bg-image');
      if (heroImgEl) {
        var fd = safeFocal(data.hero_focal_desktop), fm = safeFocal(data.hero_focal_mobile);
        if (fd) heroImgEl.style.setProperty('--hero-focal-desktop', fd);
        if (fm) heroImgEl.style.setProperty('--hero-focal-mobile', fm);
      }

      list(data.socials).slice(0, 3).forEach(function (soc, idx) {
        var platform = str(soc && soc.platform);
        var icon = Object.prototype.hasOwnProperty.call(SOCIAL_ICONS, platform) ? SOCIAL_ICONS[platform] : null;
        var href = safeHttpURL(soc && soc.url);
        if (!icon || !href) return;
        SOCIAL_LOCATIONS.forEach(function (loc) {
          var el = document.getElementById('social-' + loc + '-' + (idx + 1));
          if (!el) return;
          el.href = href;
          el.target = '_blank';
          el.rel = 'noopener noreferrer';
          el.setAttribute('aria-label', platform);
          el.innerHTML = icon;
          el.style.display = '';
        });
      });


      var menuWrap = document.getElementById('menu-section');
      var menuCategoriesWrap = document.getElementById('menu-categories');
      var categoryTemplate = document.getElementById('menu-category-template');
      if (menuCategoriesWrap && categoryTemplate) {
        clearExcept(menuCategoriesWrap, categoryTemplate);
        var maxCategories = 5, maxItemsPerCategory = 12;
        var byCategory = Object.create(null);
        var categoryOrder = [];
        list(data.menu).forEach(function (item) {
          var cat = str(item.category).trim() || 'Menu';
          if (!byCategory[cat]) {
            if (categoryOrder.length >= maxCategories) return;
            byCategory[cat] = [];
            categoryOrder.push(cat);
          }
          if (byCategory[cat].length < maxItemsPerCategory) byCategory[cat].push(item);
        });
        categoryOrder.forEach(function (catName) {
          var catBlock = cloneTemplate(categoryTemplate);
          setText(catBlock, 'category-name', catName);
          var itemsWrap = catBlock.querySelector('[data-role="menu-category-items"]');
          var itemTemplate = catBlock.querySelector('[data-role="menu-item-template"]');
          if (itemsWrap && itemTemplate) {
            byCategory[catName].forEach(function (item) {
              var card = cloneTemplate(itemTemplate);
              setText(card, 'title', item.title);
              setText(card, 'description', item.description);
              setText(card, 'price', item.price);
              showStorageImage(card, item.image);
              itemsWrap.appendChild(card);
            });
            itemTemplate.remove();
          }
          menuCategoriesWrap.appendChild(catBlock);
        });
        categoryTemplate.remove();
        if (menuWrap && categoryOrder.length > 0) menuWrap.style.display = '';
      }


      var reviewsWrap = document.getElementById('reviews-section');
      var reviewsGrid = document.getElementById('reviews-grid');
      var reviewTemplate = document.getElementById('review-card-template');
      if (reviewsGrid && reviewTemplate) {
        clearExcept(reviewsGrid, reviewTemplate);
        list(data.reviews).slice(0, 3).forEach(function (rev) {
          var card = cloneTemplate(reviewTemplate);
          var stars = Math.max(0, Math.min(5, Math.round(Number(rev.rating) || 0)));
          setText(card, 'rating', '★'.repeat(stars));
          setText(card, 'text', rev.text);
          setText(card, 'author', rev.author);
          reviewsGrid.appendChild(card);
        });
        reviewTemplate.remove();
        if (reviewsWrap && reviewsGrid.children.length > 0) reviewsWrap.style.display = '';
      }

      // Location & hours: shown only if the client configured any of it.
      var loc = data.location || {};
      var hours = list(loc.hours);
      if (loc.address || loc.phone || loc.email || hours.length > 0) {
        var section = document.getElementById('location-section');
        if (section) {
          section.style.display = '';
          if (loc.address) {
            var businessName = section.getAttribute('data-business-name') || '';
            var mapQuery = (businessName ? businessName + ', ' : '') + str(loc.address);
            var directionsURL = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(mapQuery);
            var mapEmbed = document.getElementById('location-map-embed');
            if (mapEmbed) {
              mapEmbed.src = 'https://www.google.com/maps?q=' + encodeURIComponent(mapQuery) + '&output=embed';
              mapEmbed.setAttribute('referrerpolicy', 'no-referrer-when-downgrade');
              mapEmbed.setAttribute('loading', 'lazy');
              mapEmbed.style.display = '';
            }
            var mapPlaceholder = document.getElementById('location-map-placeholder');
            if (mapPlaceholder) mapPlaceholder.style.display = 'none';
            var directionsBtn = document.getElementById('location-directions-btn');
            if (directionsBtn) { directionsBtn.href = directionsURL; directionsBtn.rel = 'noopener noreferrer'; directionsBtn.style.display = ''; }
            var addressEl = document.getElementById('location-address');
            if (addressEl) { addressEl.textContent = str(loc.address); addressEl.href = directionsURL; }
            var addressRow = document.getElementById('location-address-row');
            if (addressRow) addressRow.style.display = '';
          }
          var tel = safePhoneHref(loc.phone);
          if (loc.phone && tel) {
            var phoneEl = document.getElementById('location-phone');
            if (phoneEl) { phoneEl.textContent = str(loc.phone); phoneEl.href = tel; }
            var phoneRow = document.getElementById('location-phone-row');
            if (phoneRow) phoneRow.style.display = '';
          }
          var email = safeEmail(loc.email);
          if (email) {
            var emailEl = document.getElementById('location-email');
            if (emailEl) { emailEl.textContent = email; emailEl.href = 'mailto:' + email; }
            var emailRow = document.getElementById('location-email-row');
            if (emailRow) emailRow.style.display = '';
          }
          hours.forEach(function (h) {
            if (!h || WEEKDAYS.indexOf(h.day) === -1) return;
            var row = document.getElementById('location-hours-' + h.day);
            var value = document.getElementById('location-hours-' + h.day + '-value');
            if (!row || !value) return;
            value.textContent = h.closed ? 'Closed' : (str(h.open) + ' – ' + str(h.close));
            row.style.display = '';
          });
        }
      }

      // About: shown only if the client configured it.
      var about = data.about_me || {};
      if (about.title || about.description) {
        var aboutEl = document.getElementById('about-section');
        if (aboutEl) {
          aboutEl.style.display = '';
          var aboutTitleEl = document.getElementById('about-title');
          if (aboutTitleEl) aboutTitleEl.textContent = str(about.title);
          var aboutDescEl = document.getElementById('about-description');
          if (aboutDescEl) aboutDescEl.textContent = str(about.description);
          list(about.bullets).slice(0, 6).forEach(function (text, idx) {
            var bulletEl = document.getElementById('about-bullet-' + (idx + 1));
            if (!bulletEl) return;
            bulletEl.textContent = str(text);
            bulletEl.style.display = '';
          });
          var aboutFile = safeAssetName(about.image);
          if (aboutFile) {
            var aboutImgWrap = document.getElementById('about-image-wrap');
            var aboutImg = document.getElementById('about-image');
            if (aboutImgWrap && aboutImg) {
              aboutImgWrap.style.display = '';
              signAndSetImageEl(CLIENT_ID + '/' + aboutFile, aboutImg);
            }
          }
        }
      }
    }).catch(function () {});
  }

  loadClientData();

  // Logo: show the uploaded logo, or the business-name text if there's none.
  var logoFallback = document.getElementById('logo-fallback-text');
  signAndSetImage(CLIENT_ID + '/logo.png', 'site-logo',
    function () {
      var logo = document.getElementById('site-logo');
      if (logo) logo.classList.remove('hidden');
      if (logoFallback) logoFallback.classList.add('hidden');
    },
    function () { if (logoFallback) logoFallback.classList.remove('hidden'); });

  // Hero photo; the tint overlay only appears once a photo actually loaded.
  signAndSetImage(CLIENT_ID + '/hero.png', 'hero-bg-image', function () {
    var overlay = document.getElementById('hero-bg-overlay');
    if (overlay) overlay.style.display = '';
  });

    var galleryWrap = document.getElementById('gallery-section');
    var galleryGrid = document.getElementById('gallery-grid');
    var galleryTemplate = document.getElementById('gallery-item-template');
    if (galleryGrid && galleryTemplate) {
      clearExcept(galleryGrid, galleryTemplate);
      for (var gi = 1; gi <= 5; gi++) {
        var tile = cloneTemplate(galleryTemplate);
        signAndSetImageEl(CLIENT_ID + '/gallery-' + gi + '.png', tile.querySelector('[data-field="image"]'));
        galleryGrid.appendChild(tile);
      }
      galleryTemplate.remove();
      if (galleryWrap) galleryWrap.style.display = '';
    }

  var siteNav = document.getElementById('site-nav');
  if (siteNav) {
    var handleNavScroll = function () {
      var solid = window.scrollY > 80;
      siteNav.style.backgroundColor = solid ? 'var(--site-bg)' : 'transparent';
      siteNav.style.backdropFilter = solid ? 'blur(12px)' : 'none';
      siteNav.style.webkitBackdropFilter = solid ? 'blur(12px)' : 'none';
      siteNav.style.borderBottom = solid ? '1px solid var(--site-border)' : 'none';
    };
    window.addEventListener('scroll', handleNavScroll, { passive: true });
    handleNavScroll();
  }

  // Supabase Realtime: re-load when this client's row changes, so dashboard
  // edits appear without a reload.
  var rtRef = 0, rtWs, rtHb;
  function connectRealtime() {
    try {
      rtWs = new WebSocket(SUPABASE_URL.replace(/^https/, 'wss') + '/realtime/v1/websocket?apikey=' + encodeURIComponent(SUPABASE_ANON_KEY) + '&vsn=1.0.0');
    } catch (e) { return; }
    rtWs.onopen = function () {
      rtRef++;
      rtWs.send(JSON.stringify({ topic: 'realtime:public:clients', event: 'phx_join', payload: { config: { broadcast: { ack: false, self: false }, presence: { key: '' }, postgres_changes: [{ event: 'UPDATE', schema: 'public', table: 'clients', filter: 'id=eq.' + CLIENT_ID }] } }, ref: String(rtRef) }));
      rtHb = setInterval(function () { rtRef++; if (rtWs && rtWs.readyState === 1) rtWs.send(JSON.stringify({ topic: 'phoenix', event: 'heartbeat', payload: {}, ref: String(rtRef) })); }, 30000);
    };
    rtWs.onmessage = function (e) {
      try {
        var m = JSON.parse(e.data);
        if (m.event === 'postgres_changes') {
          try { localStorage.removeItem('cp_brand_' + CLIENT_ID); } catch (x) {}
          loadClientData();
        }
      } catch (x) {}
    };
    rtWs.onclose = function () { clearInterval(rtHb); setTimeout(connectRealtime, 5000); };
  }
  connectRealtime();
})();
